    cout << "Original List: ";
    display(head);

    // Delete 30 (last node)
    cout << "Deleting last node (30)..." << endl;
    deleteAtEnd(head);

    // Expected: 10 -> 20 -> NULL
    cout << "Resulting List: ";
    display(head);

