    insertHead(head, 30);
    insertHead(head, 20);
    insertHead(head, 10);
    cout << "List after insertions: ";
    printList(head); // 10 -> 20 -> 30 -> NULL

    deleteHead(head);
    cout << "List after deleting head: ";
    printList(head); // 20 -> 30 -> NULL

    return 0;
